powerpagecomponent.content:
{
  "filecontent": null,
  "displayorder": 5,
  "customcss": ".tab-column{
    width: 100% !important;
}


#MessagePanel {
    display: none !important;
}


.cmdspp-registration-page{
    min-height:calc(100vh - 124px);
    display:flex;
    justify-content:space-around;
    align-items:center;
    padding: 80px 40px 96px 40px;
}

.cmdspp-registration-left{
    width:45%;
}

.cmdspp-portal-badge{
    display:inline-block;
    background:#0B3A6F1A;
    border:1px solid #0B3A6F26;
    padding:7px 17px;
    border-radius:20px;
    color:#0B3A6FE5;
    margin-bottom:30px;
    font-weight: 400;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0.3px;
    text-transform: uppercase;
    span{
        color: #00D492 !important;
    }
}

.cmdspp-registration-left h1{
    color: #0B3A6F;
    font-size: 54px;
    font-weight: 400 !important;
    line-height: 62px;
    margin-bottom: 33px;
}

.cmdspp-description{
    max-width: 425px;
    color: #0B3A6F;
    font-weight: 400 !important;
    font-size: 16px;
    line-height: 26px;
    letter-spacing: 0px;
    margin-bottom: 61px;
}

.cmdspp-benefits div{
    margin-bottom: 10px;
    color: #0B3A6F;
    font-size: 14px;
    line-height: 20px;
    font-weight: 400 !important;
}

.cmdspp-registration-right{
    width:460px;
}

.cmdspp-registration-card{
    background:#fff;
    border-radius:16px;
    padding:32px;
    border-top:4px solid #295a9f;
    box-shadow:0 8px 20px rgba(0,0,0,.08);
    .cmdspp-registration-cardheading{
        display: flex;
        justify-content: center;
        font-size: 23px;
        color: #274463;
        line-height: 34px;
        font-weight: 400 !important;
    }
    .cmdspp-registration-cardfooter{
        font-size: 12px;
        color: #0B3A6F;
        font-weight: 400;
        line-height: 16px;
        margin-top: 14px;
        justify-content: center;
        display: flex;
    }
    .crmEntityFormView{
        border: none !important;
        .cell{
            padding: 0 0 16px !important;
        }
        .actions{
            margin: 0px !important;
            padding: 0px !important;
            border: none !important;
        }
        .fieldset,
        .tab{
            margin-bottom: 0px !important;
        }
    }
}

.cmdspp-registration-card h1,
.cmdspp-registration-card h2,
.cmdspp-registration-card .entity-form-title{
    text-align:center;
    color:#27456f;
}

.cmdspp-field-error {
    box-shadow: inset 0 0 0 1px #CD3D64, 0 0 0 2px #FDE2DD !important;
}


/* form labels */
.cmdspp-registration-card label{
    font-size: 12px;
    color: #0B3A6F;
    font-weight: 400;
    line-height: 16px;
    margin-bottom: 4px;
}

/* form a tag */
.cmdspp-registration-card a{
    font-size: 12px;
    color: #1C70DE;
    font-weight: 400;
    line-height: 16px;
    margin-left: 5px;
}

#termsCheckboxContainer label{
    display: flex;
    gap: 8px;
    align-items: center;
    margin-bottom: 0px !important;
}

#termsCheckbox{
    margin-top: 0px !important;
    width: 20px;
    height: 20px;
    accent-color: #274463;
}

/* inputs */
.cmdspp-registration-card input[type="text"],
.cmdspp-registration-card input[type="email"],
.cmdspp-registration-card input[type="tel"],
.cmdspp-registration-card select{
    height:36px;
    border:1px solid #E3E8EE;
    border-radius:4px;
    box-shadow: 0px 1px 2px 0px #37415114;
    font-weight: 400 !important;
    font-size: 14px;
    line-height: 24px;
    color: #0B3A6F;
    text-decoration: none !important;
}


.cmdspp-registration-card input[type="text"]::placeholder,
.cmdspp-registration-card input[type="email"]::placeholder,
.cmdspp-registration-card input[type="tel"]::placeholder {
    text-decoration: none !important;
    font-size: 14px;
    font-weight: 400 !important;
    line-height: 20px;
    color: #0B3A6F; 
    opacity: 0.4;
}

.cmdspp-registration-card input[type="text"]:focus,
.cmdspp-registration-card input[type="email"]:focus,
.cmdspp-registration-card input[type="tel"]:focus {
    box-shadow: 0px 0px 0px 1px #6C8EEF inset, 0px 0px 0px 2px #D6ECFF;
}


/* submit button */
/* .cmdspp-registration-card .btn-primary,
.cmdspp-registration-card input[type="submit"]{
    background:#243f6b !important;
    border-color:#243f6b !important;
    width:100%;
    height:44px;
    border-radius:6px;
} */

.cmdspp-registration-actions{
    display:flex;
    gap:24px;
    /* margin-top:8px; */
}

.cmdspp-btn-secondary,
.cmdspp-btn-primary{
    flex:1;
    height:40px;
    border-radius:8px;
    font-weight: 400 !important;
    font-size: 14px;
    line-height: 20px;
    letter-spacing: 0px;
    text-align: center;
    cursor:pointer;
    box-shadow: 0px 1px 2px -1px #0000001A;
}

.cmdspp-btn-secondary{
    background:#ffffff;
    border:1px solid #274463;
    color: #274463;
}

.cmdspp-btn-primary{
    background:#274463;
    border:1px solid #274463;
    color:#ffffff;
}

#cmdsppSubmitBtn:disabled{
    background: #274463;
    opacity: 0.5 !important;
    box-shadow: 0px 1px 2px -1px #0000001A, 0px 1px 3px 0px #0000001A;
    color:#ffffff;
}

#InsertButton {
    display: none !important;
}

/* checkbox row */
.cmdspp-registration-card .checkbox{
    margin-top:15px;
}

/* form header */
.cmdspp-registration-card .form-title,
.cmdspp-registration-card .entity-form-title{
    font-size:34px;
    margin-bottom:20px;
}

.validation-summary {
    display: none !important;
}


/* responsive */
@media(max-width:1200px){

    .cmdspp-registration-page{
        flex-direction:column;
        gap:40px;
    }

    .cmdspp-registration-left{
        width:100%;
    }

    .cmdspp-registration-right{
        width:100%;
        max-width:550px;
    }

}

#cmdspp_g_tms_n_condtns_label{
    display: none !important
}

.crmEntityFormView .cell div.table-info.required label:after {
    position: relative;
    left: -3px;
}",
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "parentpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "partialurl": "User-registration",
  "isroot": false,
  "rootwebpageid": "87a8a070-d38f-bb02-ffbb-ca2e5ce3050c",
  "title": "User registration",
  "summary": "<p>This is a sample landing page designed to be a starting point for your website</p>",
  "copy": "<div class="cmdspp-registration-page cmdspp-registration-pages-bg">
  <div class="cmdspp-registration-left">
    <div class="cmdspp-portal-badge"><span class="cmds-portal-badge-dot">●</span> OFFICIAL GOVERNMENT PORTAL · SECURE CONNECTION</div>
    <h1>Connecting Healthcare Professionals Across the Nation</h1>
    <p class="cmdspp-description">The National Medical Enrollment Portal is the single authoritative registry for licensed physicians, specialists, and allied health professionals operating within the national healthcare system.</p>
    <div class="cmdspp-benefits">
      <div><img src="/cmdspp_greenTickCircle"/>  HIPAA Compliant Infrastructure</div>
      <div><img src="/cmdspp_greenTickCircle"/>  256-bit TLS Encryption</div>
      <div><img src="/cmdspp_greenTickCircle"/>  ISO 27001:2022 Certified</div>
    </div>
  </div>
  <div class="cmdspp-registration-right">
    <div class="cmdspp-registration-card">
      <div class="cmdspp-registration-cardheading">New User Registration</div>
      {% entityform name: 'User Register' %}
      <div class="cmdspp-registration-actions">

    <button
        type="button"
        id="cmdsppCancelBtn"
        class="cmdspp-btn-secondary">
        Cancel
    </button>

    <button
        type="button"
        id="cmdsppSubmitBtn"
        class="cmdspp-btn-primary" disabled>
        Submit
    </button>

</div>
      <div class="cmdspp-registration-cardfooter">Already have an account? <a href="/signIn"> Login</a></div>
    </div>
  </div>
</div>
<div class="row sectionBlockLayout text-start" style="display: none; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;"><div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px;"></div></div>
</div>",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "hiddenfromsitemap": true,
  "sharedpageconfiguration": false,
  "feedbackpolicy": 756150000,
  "customjavascript": "$(window).on('load', function () {

    // Hide the entire radio control
    $("#cmdspp_g_tms_n_condtns").hide();

    // Add checkbox after it
    $("#cmdspp_g_tms_n_condtns").after(`
        <div id="termsCheckboxContainer">
            <label>
                <input type="checkbox" id="termsCheckbox">                
                 <span class="cmdss-registration-checkbox-label-container">I have read and agree with the <a href="/cmdspp-acceptable-use-policy" target="_blank">Acceptable Use Policy</a></span>
            </label>
        </div>
    `);

    $("#termsCheckbox").change(function () {

        if ($(this).is(":checked")) {
            $("#cmdspp_g_tms_n_condtns_1").prop("checked", true);
        } else {
            $("#cmdspp_g_tms_n_condtns_0").prop("checked", true);
        }

        $("#cmdspp_g_tms_n_condtns_1").trigger("change");
    });


    $("input[type='text'], input[type='email'], textarea")
        .attr("placeholder", "Enter Text");

    $("#cmdspp_g_phn_num")
        .attr("placeholder", "Enter Number");

    $("input[type='text'], input[type='email'], textarea")
        .attr("title", "");

});

$(document).on(
    "input",
    "input, textarea",
    function () {

        $(this).removeClass("cmdspp-field-error");
        document.getElementById("cmdsppSubmitBtn").disabled = false;

    }
);

function highlightValidationFields() {
if ($(".validation-summary a").length){
    $(".validation-summary a").each(function () {

    const targetId =
        $(this).attr("href")?.replace("#", "");

    const label =
        $("#" + targetId);

    const inputId =
        label.attr("for");

    if (inputId) {

        $("#" + inputId)
            .addClass("cmdspp-field-error");

    }

});    
    const firstError =$(".validation-summary a").first();

    if (firstError.length) {

       const errorMessage =firstError.text().trim();
       cmdsppShowToast("error",errorMessage);
   }
   return
}


// Duplicate key handling
    const duplicateError = $(".text-danger");

    if (duplicateError.length) {

        // const errorText =
        //     duplicateError.text().trim();


        //     cmdsppShowToast("error","An account with the entered email address already exists");

        //     $("#cmdspp_g_email").addClass("cmdspp-field-error");

            const errorMessage = document.querySelector(".text-danger")?.innerText || "";

            if(errorMessage.includes("UniqEmailKey")){
               cmdsppShowToast("error","An account with the entered email address already exists");
               $("#cmdspp_g_email").addClass("cmdspp-field-error");
            }else{
                cmdsppShowToast("error","Phone Number is already used.");
                $("#cmdspp_g_phn_num").addClass("cmdspp-field-error");
            }

            return;
        

    }

}

const observer = new MutationObserver(function () {

    if ($(".validation-summary a").length || $(".text-danger").length) {

        highlightValidationFields();
        document.getElementById("cmdsppSubmitBtn").disabled = false;
        setTimeout(() => {
            if($("#termsCheckbox")){
               $("#termsCheckbox").prop("checked", true).trigger("change");
               $("#cmdspp_g_tms_n_condtns_1").prop("checked", true);
               $("#cmdspp_g_tms_n_condtns_1").trigger("change");
            }
            
        }, 500);
        

        observer.disconnect();
    }

});

observer.observe(document.body, {
    childList: true,
    subtree: true
});

function showValidationError(field, message) {

    // Highlight current field
    $(field).addClass("cmdspp-field-error");

    // Show toast
   cmdsppShowToast("error",message);

    // Focus field
    // field.focus();

    return false;
}

function validateRegistrationForm() {

    const firstName = $("#cmdspp_g_fst_nam");
    const lastName = $("#cmdspp_g_lst_nam");
    const email = $("#cmdspp_g_email");
    const phone = $("#cmdspp_g_phn_num");
    const organization = $("#cmdspp_g_org_nam");

    const nameRegex = /^[A-Za-z0-9\s'-]+$/;
    // const nameRegex = /^[A-Za-z]+(?:[ '-][A-Za-z]+)*$/;

    const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // First Name
    if (!firstName.val().trim()) {
        return showValidationError(firstName[0], "First name is required");
    }

    if (!nameRegex.test(firstName.val().trim())) {
        return showValidationError(
            firstName[0],
            "First name contains invalid characters"
        );
    }

    // Last Name
    if (!lastName.val().trim()) {
        return showValidationError(lastName[0], "Last name is required");
    }

    if (!nameRegex.test(lastName.val().trim())) {
        return showValidationError(
            lastName[0],
            "Last name contains invalid characters"
        );
    }

    // Email
    if (!email.val().trim()) {
        return showValidationError(email[0], "Email address is required");
    }

    if (!emailRegex.test(email.val().trim())) {
        return showValidationError(email[0], "Enter a valid email address");
    }

    // Phone
    if (!phone.val().trim()) {
        return showValidationError(phone[0], "Phone number is required");
    }

    if (!phoneRegex.test(phone.val().trim())) {
        return showValidationError(
            phone[0],
            "Not a valid phone number"
        );
    }

    // Organization (optional)
    if (
        organization.val().trim() &&
        !nameRegex.test(organization.val().trim())
    ) {
        return showValidationError(
            organization[0],
            "Organization Name contains invalid characters"
        );
    }

    if (!$("#termsCheckbox").is(":checked")) {
 
       return showValidationError(
            $("#termsCheckbox")[0],
            "Please accept the Terms and Conditions"
        );
    }

    // Clear highlights when valid
    // $(".field-error").removeClass("field-error");

    return true;
}

$("#cmdspp_g_phn_num").on("input", function () {

    let value = $(this).val().replace(/\D/g, "");

    value = value.substring(0, 10);

    if (value.length > 6) {

        value =
            value.substring(0, 3) +
            "-" +
            value.substring(3, 6) +
            "-" +
            value.substring(6);

    }
    else if (value.length > 3) {

        value =
            value.substring(0, 3) +
            "-" +
            value.substring(3);

    }

    $(this).val(value);

});

$(document).ready(function () {

    $("#cmdsppSubmitBtn").on("click", function () {

        if(validateRegistrationForm()){
           const nativeSubmit = $("#InsertButton");
            // $(".crmEntityFormView input[type='submit']:first");

        if (nativeSubmit.length) {

            nativeSubmit.trigger("click");

        }
        }

        

    });

    $("#cmdsppCancelBtn").on("click", function () {

        window.location.href = "/";

    });

});"
}
